function fixed(int $value, int $places): string
    $scale = 10 ** $places;
    return intdiv($value, $scale) . '.' . str_pad((string) ($value % $scale), $places, '0', STR_PAD_LEFT);
function percentage(int $part, int $whole): string
    return fixed(intdiv(10000 * $part, $whole), 2);
